// Grid on/off and battery-low alerts. State is remembered between runs
// (only while the workflow is ACTIVE; manual test runs don't keep state).
const d = $input.first().json;
const s = $getWorkflowStaticData('global');
const LOW = 30;        // alert when battery falls to this % (grid off)
const RECOVER = 40;    // re-arm the low alert once back above this %
const now = Date.now();
const time = new Date().toLocaleTimeString('en-GB', { timeZone: 'Africa/Lagos', hour: '2-digit', minute: '2-digit' });
const dur = (ms) => { const m = Math.round(ms / 60000), h = Math.floor(m / 60); return h ? `${h} h ${m % 60} min` : `${m} min`; };
const hm = (h) => { const m = Math.round(h * 60); return Math.floor(m / 60) ? `${Math.floor(m / 60)} h ${m % 60} min` : `${m % 60} min`; };
const out = [];

if (d.grid_present === undefined || d.bat_soc === undefined) return [];
const grid = d.grid_present >= 1;
const soc = Math.round(d.bat_soc);

if (s.grid === undefined) {          // first run: just remember the current state
  s.grid = grid; s.since = now;
} else if (grid !== s.grid) {
  const lasted = dur(now - s.since);
  if (!grid) {
    out.push(`⚡ Grid is OFF (${time}), after ${lasted} on.\nBattery ${soc}%` +
      (d.night_runtime_hours ? `: about ${hm(d.night_runtime_hours)} at the current load without solar.` : '.'));
  } else {
    out.push(`✅ Grid is back (${time}) after ${lasted} off.\nBattery ${soc}%.`);
  }
  s.grid = grid; s.since = now;
}

if (!grid && !s.lowSent && d.bat_soc <= LOW) {
  out.push(`🔋 Battery low: ${soc}%` +
    (d.runtime_hours ? `, about ${hm(d.runtime_hours)} left at the current draw.` : '.') +
    `\nConsider switching off heavy appliances.`);
  s.lowSent = true;
}
if (s.lowSent && d.bat_soc >= RECOVER) s.lowSent = false;

return out.map(text => ({ json: { text } }));

// Hourly status message from the inverter exporter.
const QUIET_HOURS = [];   // e.g. [0,1,2,3,4,5] to skip messages from midnight to 5am
const d = $input.first().json;
const hour = Number(new Date().toLocaleString('en-GB', { timeZone: 'Africa/Lagos', hour: '2-digit', hour12: false }));
if (QUIET_HOURS.includes(hour) || d.bat_soc === undefined) return [];

const hm = (h) => { const m = Math.round(h * 60); return Math.floor(m / 60) ? `${Math.floor(m / 60)} h ${m % 60} min` : `${m % 60} min`; };
const w = (x) => `${Math.round(x)} W`;
const time = new Date().toLocaleTimeString('en-GB', { timeZone: 'Africa/Lagos', hour: '2-digit', minute: '2-digit' });
const grid = d.grid_present >= 1;

let battery = `🔋 Battery ${Math.round(d.bat_soc)}%`;
if (d.bat_power > 10) battery += ` (charging ${w(d.bat_power)})`;
else if (d.bat_power < -10) battery += ` (discharging ${w(-d.bat_power)})`;

const lines = [
  `🕐 ${time} status`,
  grid ? `⚡ Grid: ON` : `⚠️ Grid: OFF`,
  battery,
  `☀️ Solar ${w(d.pv_power ?? 0)} · 🏠 Load ${w(d.load_power ?? 0)}`,
];

if (grid) {
  if (d.night_runtime_hours !== undefined)
    lines.push(`⏳ If the grid goes off: ~${hm(d.night_runtime_hours)} at this load (no solar)`);
} else {
  const parts = [];
  if (d.night_runtime_hours !== undefined) parts.push(`~${hm(d.night_runtime_hours)} without solar`);
  if (d.runtime_hours !== undefined) parts.push(`~${hm(d.runtime_hours)} at current draw`);
  if (parts.length) lines.push(`⏳ Battery lasts ${parts.join(' · ')}`);
}
return [{ json: { text: lines.join('\n') } }];

// Daily summary: power, internet, media and server stats since midnight (Lagos).
// API keys come from homepage.secret via $env (never stored in this workflow).
const LAN = 'http://192.168.3.201', PVE = 'https://192.168.3.200:8006', PROM = `${LAN}:9090/api/v1/query`;
const env = (k) => $env[`HOMEPAGE_VAR_${k}`] || '';
const helpers = this.helpers;
const http = (opts) => helpers.httpRequest({ json: true, timeout: 15000, ...opts });
const safe = async (fn) => { try { return await fn(); } catch (e) { return null; } };
const prom = async (expr) => {
  const r = await http({ url: PROM, qs: { query: expr } });
  const v = r?.data?.result?.[0]?.value?.[1];
  return v === undefined ? null : Number(v);
};

// --- time window ---
const lagos = new Date(new Date().toLocaleString('en-US', { timeZone: 'Africa/Lagos' }));
const pad = (n) => String(n).padStart(2, '0');
const today = `${lagos.getFullYear()}-${pad(lagos.getMonth() + 1)}-${pad(lagos.getDate())}`;
const midnightISO = `${today}T00:00:00+01:00`;
const since = new Date(midnightISO).getTime();
const mins = Math.max(lagos.getHours() * 60 + lagos.getMinutes(), 1), W = `${mins}m`, H = mins / 60;
const hm = (h) => { const m = Math.round(h * 60); return Math.floor(m / 60) ? `${Math.floor(m / 60)} h ${m % 60} min` : `${m % 60} min`; };
const naira = (n) => '₦' + Math.round(n).toLocaleString('en-NG');
const list = (arr, max = 3) => arr.slice(0, max).join(', ') + (arr.length > max ? ` +${arr.length - max} more` : '');
const sonarrH = { 'X-Api-Key': env('SONARR_KEY') }, radarrH = { 'X-Api-Key': env('RADARR_KEY') }, lidarrH = { 'X-Api-Key': env('LIDARR_KEY') };

const tasks = {
  power: safe(async () => Promise.all([
    prom(`avg_over_time(felicity_grid_present[${W}]) * ${H}`),
    prom(`resets(felicity_grid_present[${W}])`),
    prom(`increase(felicity_pv_energy_kwh_total[${W}])`),
    prom(`increase(felicity_load_energy_kwh_total[${W}])`),
    prom(`felicity_battery_soc_percent`),
    prom(`min_over_time(felicity_battery_soc_percent[${W}])`),
    prom(`felicity_tariff_ngn_per_kwh`),
    prom(`felicity_generator_cost_ngn_per_kwh`),
  ])),
  internet: safe(() => prom('odu_day_used_bytes')),
  streaming: safe(async () => {
    const q = (sql) => http({ method: 'POST', url: `${LAN}:8096/user_usage_stats/submit_custom_query`,
      headers: { 'X-Emby-Token': env('JELLYFIN_KEY') }, body: { CustomQueryString: sql, ReplaceUserId: true } });
    const day = `date(DateCreated) = '${today}'`;
    const total = await q(`SELECT COALESCE(SUM(PlayDuration),0), COUNT(*) FROM PlaybackActivity WHERE ${day}`);
    const top = await q(`SELECT ItemName, SUM(PlayDuration) AS s FROM PlaybackActivity WHERE ${day} GROUP BY ItemName ORDER BY s DESC LIMIT 3`);
    return { seconds: Number(total.results?.[0]?.[0] || 0), plays: Number(total.results?.[0]?.[1] || 0),
             top: (top.results || []).map(r => r[0]) };
  }),
  listening: safe(async () => {
    const r = await http({ url: `${LAN}:13378/api/me/listening-stats`, headers: { Authorization: `Bearer ${env('AUDIOBOOKSHELF_KEY')}` } });
    return Number(r?.days?.[today] || 0);
  }),
  episodes: safe(async () => {
    const r = await http({ url: `${LAN}:8989/api/v3/history/since`, headers: sonarrH, qs: { date: midnightISO, includeSeries: true, includeEpisode: true } });
    return r.filter(x => x.eventType === 'downloadFolderImported')
            .map(x => `${x.series?.title ?? 'Unknown'} S${pad(x.episode?.seasonNumber ?? 0)}E${pad(x.episode?.episodeNumber ?? 0)}`);
  }),
  movies: safe(async () => {
    const r = await http({ url: `${LAN}:7878/api/v3/history/since`, headers: radarrH, qs: { date: midnightISO, includeMovie: true } });
    return [...new Set(r.filter(x => x.eventType === 'downloadFolderImported').map(x => x.movie?.title ?? 'Unknown'))];
  }),
  music: safe(async () => {
    const r = await http({ url: `${LAN}:8686/api/v1/history/since`, headers: lidarrH, qs: { date: midnightISO, includeAlbum: true, includeArtist: true } });
    const tracks = r.filter(x => x.eventType === 'trackFileImported');
    return { tracks: tracks.length, albums: [...new Set(tracks.map(x => `${x.album?.title ?? '?'} (${x.artist?.artistName ?? '?'})`))] };
  }),
  tomorrow: safe(async () => {
    const start = new Date(since + 86400000).toISOString(), end = new Date(since + 2 * 86400000).toISOString();
    const r = await http({ url: `${LAN}:8989/api/v3/calendar`, headers: sonarrH, qs: { start, end, includeSeries: true } });
    return r.map(x => `${x.series?.title ?? 'Unknown'} S${pad(x.seasonNumber)}E${pad(x.episodeNumber)}`);
  }),
  requests: safe(async () => {
    const r = await http({ url: `${LAN}:5055/api/v1/request`, headers: { 'X-Api-Key': env('SEERR_KEY') }, qs: { take: 100, skip: 0, sort: 'added', filter: 'all' } });
    return (r.results || []).filter(x => new Date(x.createdAt).getTime() >= since).length;
  }),
  photos: safe(async () => http({ url: `${LAN}:2283/api/server/statistics`, headers: { 'x-api-key': env('IMMICH_KEY') } })),
  server: safe(async () => {
    const h = { Authorization: `PVEAPIToken=${env('PROXMOX_TOKEN_ID')}=${env('PROXMOX_TOKEN_SECRET')}` };
    const get = (path) => http({ url: `${PVE}/api2/json${path}`, headers: h, skipSslCertificateValidation: true }).then(r => r.data);
    const [pool, ct, node] = await Promise.all([get('/nodes/pve/storage/local-lvm/status'), get('/nodes/pve/lxc/201/status/current'), get('/nodes/pve/status')]);
    return { pool: pool.used / pool.total * 100, disk: ct.disk / ct.maxdisk * 100, uptime: node.uptime };
  }),
};
const r = Object.fromEntries(await Promise.all(Object.entries(tasks).map(async ([k, p]) => [k, await p])));

// --- build the message ---
const day = lagos.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' });
const L = [`📊 Daily summary: ${day}`];

if (r.power) {
  const [gridH, outages, solar, load, socNow, socMin, tariff, gen] = r.power;
  if (gridH !== null) L.push(`⚡ Grid: ${hm(gridH)}` + (outages !== null ? ` (${outages} power cut${outages === 1 ? '' : 's'})` : ''));
  if (solar !== null) L.push(`☀️ Solar ${solar.toFixed(1)} kWh · 🏠 Used ${load?.toFixed(1) ?? '?'} kWh`);
  if (solar !== null && tariff) L.push(`💰 Solar saved ${naira(solar * tariff)} vs grid` + (gen ? ` (${naira(solar * gen)} vs generator)` : ''));
  if (socNow !== null) L.push(`🔋 Battery now ${Math.round(socNow)}%` + (socMin !== null ? ` (lowest today ${Math.round(socMin)}%)` : ''));
}
if (r.internet !== null) L.push(`📶 Internet today: ${(r.internet / 1e9).toFixed(1)} GB`);

const media = [];
if (r.streaming && r.streaming.seconds > 0) media.push(`🎬 Streamed ${hm(r.streaming.seconds / 3600)} on Jellyfin (${r.streaming.plays} play${r.streaming.plays === 1 ? '' : 's'})` + (r.streaming.top.length ? `\n    Top: ${list(r.streaming.top)}` : ''));
if (r.listening) media.push(`🎧 Listened to audiobooks for ${hm(r.listening / 3600)}`);
const got = [];
if (r.episodes?.length) got.push(`${r.episodes.length} episode${r.episodes.length === 1 ? '' : 's'}`);
if (r.movies?.length) got.push(`${r.movies.length} movie${r.movies.length === 1 ? '' : 's'}`);
if (r.music?.tracks) got.push(`${r.music.tracks} track${r.music.tracks === 1 ? '' : 's'}`);
if (got.length) {
  media.push(`📥 New today: ${got.join(', ')}`);
  if (r.movies?.length) media.push(`    Movies: ${list(r.movies)}`);
  if (r.episodes?.length) media.push(`    Shows: ${list([...new Set(r.episodes.map(e => e.replace(/ S\d+E\d+$/, '')))])}`);
  if (r.music?.albums?.length) media.push(`    Music: ${list(r.music.albums, 2)}`);
}
if (r.requests) media.push(`🙋 ${r.requests} new request${r.requests === 1 ? '' : 's'} in Seerr`);
if (r.tomorrow?.length) media.push(`📅 Tomorrow: ${list(r.tomorrow)}`);

const s = $getWorkflowStaticData('global');
if (r.photos) {
  const prev = s.immich;
  if (prev && prev.date !== today) {
    const p = r.photos.photos - prev.photos, v = r.photos.videos - prev.videos;
    if (p > 0 || v > 0) media.push(`📸 ${p} photo${p === 1 ? '' : 's'}` + (v ? ` and ${v} video${v === 1 ? '' : 's'}` : '') + ' backed up to Immich');
  }
  s.immich = { date: today, photos: r.photos.photos, videos: r.photos.videos };
}
if (media.length) L.push('', ...media);

if (r.server) {
  const flag = (x) => (x >= 80 ? ' ⚠️' : '');
  L.push('', `💾 Storage pool ${Math.round(r.server.pool)}%${flag(r.server.pool)} · docker disk ${Math.round(r.server.disk)}%${flag(r.server.disk)}`,
            `🖥️ Server up ${Math.floor(r.server.uptime / 86400)} d ${Math.floor(r.server.uptime % 86400 / 3600)} h`);
  if (r.server.pool >= 80 || r.server.disk >= 80) L.push('⚠️ Free some space soon: delete watched media, then run pct fstrim 201.');
}
return [{ json: { text: L.join('\n') } }];
